B.a43=new A.an("M\u0259xfilik","\u0130stifad\u0259\xe7i m\u0259lumatlar\u0131n\u0131n m\u0259xfiliyi qorunur. M\u0259lumatlar \xfc\xe7\xfcnc\xfc t\u0259r\u0259fl\u0259r\u0259 yaln\u0131z qanunvericiliyin t\u0259l\u0259b etdiyi hallarda t\u0259qdim olunur.",t.R)
B.a46=new A.an("\xd6d\u0259ni\u015fl\u0259r","Kart m\u0259lumatlar\u0131 Workspot t\u0259r\u0259find\u0259n saxlan\u0131lm\u0131r v\u0259 emal edilmir. \xd6d\u0259ni\u015fl\u0259r Epoint / PA\u015eA Bank t\u0259r\u0259find\u0259n t\u0259hl\xfck\u0259siz \u015f\u0259kild\u0259 emal olunur.",t.R)
B.a4h=new A.an("Paketl\u0259rin aktivl\u0259\u015fdirilm\u0259si","\xd6d\u0259nilmi\u015f paketl\u0259r \xf6d\u0259ni\u015f t\u0259sdiql\u0259ndikd\u0259n d\u0259rhal sonra an\u0131nda aktiv olunur.",t.R)
B.a4b=new A.an("\u0130mtina / Qaytarma \u015e\u0259rtl\u0259ri","Paket aktivl\u0259\u015fdirildikd\u0259n sonra xidm\u0259t g\xf6st\u0259rilmi\u015f hesab olunur. Texniki x\u0259ta v\u0259 ya t\u0259krar \xe7\u0131x\u0131lma hallar\u0131nda support@workspot.az \xfcnvan\u0131na m\xfcraci\u0259t ed\u0259 bil\u0259rsiniz.",t.R)
